CREATE TABLE IF NOT EXISTS "Episodes" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "AnimeId" integer NOT NULL,
    "EpisodeNumber" integer NOT NULL,
    "Title" text NOT NULL,
    "EmbedUrl" text,
    "HlsUrl" text,
    "ServerName" text NOT NULL,
    "SubtitlesJson" text,
    "CreatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_Episodes" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Episodes_AnimeCaches_AnimeId" FOREIGN KEY ("AnimeId") REFERENCES "AnimeCaches" ("Id") ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS "IX_Episodes_AnimeId_EpisodeNumber" ON "Episodes" ("AnimeId", "EpisodeNumber");

ALTER TABLE "AnimeCaches" ADD COLUMN IF NOT EXISTS "CurrentEpisodes" integer;
ALTER TABLE "AnimeCaches" ADD COLUMN IF NOT EXISTS "EndDate" text;
ALTER TABLE "AnimeCaches" ADD COLUMN IF NOT EXISTS "LastAiredAt" timestamp with time zone;

